#### CodeForces - 1921A
https://vjudge.net/problem/CodeForces-1921A
问题在于乱序给出点位，通用解法是海伦公式
```cpp
double areaOfTriangle(pair<int, int>& p1, pair<int, int>& p2, pair<int, int>& p3) {
	double a	  = sqrt(pow(p1.first - p2.first, 2) + pow(p1.second - p2.second, 2));
	double b	  = sqrt(pow(p1.first - p3.first, 2) + pow(p1.second - p3.second, 2));
	double c	  = sqrt(pow(p2.first - p3.first, 2) + pow(p2.second - p3.second, 2));
	double s	  = (a + b + c) / 2.0;
	double result = sqrt(s * (s - a) * (s - b) * (s - c));
	return result;
}
// 
int main() {
	deque<pair<int, int>> points;
	int					  round, x, y;
	cin >> round;
	double area = 0.0;
	for(int i = 0; i < round; i++) {
		area = 0.0;
		for(int j = 0; j < 4; j++) {
			cin >> x >> y;
			pair<int, int> point(x, y);
			if(points.size() < 2) {
				points.emplace_back(point);
			} else if(points.size() == 2) {
				auto a = points.front();
				points.pop_front();
				auto b = points.front();
				points.pop_front();
				area += areaOfTriangle(a, b, point);
				points.emplace_back(b);
				points.emplace_back(point);
			}
		}
		points.clear();
		cout << static_cast<int>(::round(area)) << '\n';
	}
}
```
实际上本题没有必要用浮点算法，因为正方形且变长是整数，所以结果一定是整数，暴力分出两组平行边即可

